fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // Under the problem's assumption, all three vectors have the same length.
    let len = condition.len();
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        // If the mask at position i is true, choose x[i], otherwise choose y[i].
        if condition[i] {
            result.push(x[i]);
        } else {
            result.push(y[i]);
        }
    }

    result
}

